#!/usr/bin/env python3
"""Film Part 3: AI/ML for Film, Product/UX, Data Systems -- pairs for upgrade_b"""
import json, pathlib

OUT = pathlib.Path('/workspace/data_upgrades/upgrade_b.jsonl')
OUT.parent.mkdir(parents=True, exist_ok=True)

pairs = [
# ── AI AND MACHINE LEARNING FOR FILM ─────────────────────────────────────────
("How does NLP (natural language processing) apply to script analysis?", "NLP applications in script analysis: (1) Scene breakdown automation -- NLP models parse scene headings (INT./EXT., location, time of day), character cues, action lines, and dialogue into structured data; eliminates manual breakdown for scheduling and budgeting. (2) Character dialogue analysis -- count and analyse dialogue per character; track vocabulary patterns, speech rhythm, and linguistic markers that reveal character; identify where a character's voice changes (arc marker). (3) Sentiment analysis -- sentence-level and scene-level sentiment scoring reveals the emotional pacing of the script; a graph of scene-by-scene sentiment score flags flat sections and missing emotional beats. (4) Entity extraction -- automatically extract all proper nouns (character names, location names, prop names) from action lines; cross-reference against production database. (5) Revision diffing -- NLP-powered diff tools compare two script versions at the semantic level (not just string diff); highlight changes in character motivation or scene objective even when the surface dialogue has changed. (6) Dialogue quality analysis -- models trained on produced screenplays can flag dialogue that is on-the-nose (characters stating subtext directly), overly expository, or tonally inconsistent with the rest of the script. (7) Genre and tone classification -- classify the overall script tone and genre based on word choice, scene distribution, and structural patterns; useful for early development comparison against market comparables. Limitations: current NLP models understand language at the surface level; they cannot evaluate the quality of dramatic construction, emotional truth, or artistic originality -- these remain human critical faculties."),
("How does computer vision apply to film production and post-production?", "Computer vision applications across the film pipeline: (1) Scene and shot tagging -- CV models automatically tag footage with scene type (interior/exterior), time of day, weather conditions, dominant colours, present characters (face recognition), camera movement type; enables rapid search across large footage archives. (2) Continuity checking -- comparing frames from different takes or shooting days to flag continuity errors (prop position changes, costume differences, hair/makeup inconsistencies) before they reach the edit. (3) Face recognition for casting and clearances -- identifying all faces in footage for talent clearance tracking; flagging background performers who need release forms. (4) Automated dailies review -- CV-based quality control detects technical issues (out-of-focus frames, exposure clipping, motion blur) in footage before it reaches the editor. (5) AI-based video restoration -- neural network upscaling, grain removal, and colour restoration for archival footage (used on Star Wars: The Mandalorian for legacy footage integration). (6) Deepfake and de-aging -- face replacement and age modification through generative CV models (Indiana Jones 5's digital de-aging of Harrison Ford; The Irishman's face replacement technology). (7) Shot matching for VFX -- CV algorithms automatically match colour, grain, and lens characteristics between production plates and CG elements. (8) Pre-vis from storyboard -- emerging models translate 2D storyboard frames into 3D pre-visualisation sequences automatically. Limitation: CV models in production are tools for efficiency, not creative decision-making; the human eye remains the final arbiter of image quality and artistic intent."),
("What are multimodal AI systems and how do they apply to film production workflows?", "Multimodal AI systems process and generate across multiple data types simultaneously -- text, image, audio, and video. Applications in film production: (1) Script-to-storyboard -- a multimodal model reads a scene description from the script and generates candidate storyboard frames illustrating the written action; the director reviews, selects, and modifies; reduces the time to visual communication of intent. (2) Reference image analysis -- a director uploads a reference image (from another film, a painting, a photograph) and the AI analyses its compositional principles, lighting characteristics, and colour palette; generates a written description that can be shared with the DP as a precise reference. (3) Location scouting assistance -- analyse photographs of potential locations against the script's requirements and the mood board; rank locations by visual match score. (4) Dialogue and visuals together -- multimodal models can analyse whether a scene's dialogue and described visuals are tonally consistent; flag moments where the action description and dialogue are working against each other. (5) Sound design brainstorming -- given scene description and visual references, suggest candidate sound design approaches and specific sound effects. (6) Film analysis -- analyse existing films at the scene level across visual (composition, lighting), audio (dialogue, music, sound design), and narrative dimensions to extract directorial and editorial patterns. (7) Automated subtitle generation -- speech-to-text transcription combined with timing and speaker diarisaton. Current state: multimodal AI tools (GPT-4V, Gemini Pro Vision, Claude) are powerful for analysis and ideation but not yet reliable for direct production deliverables; human review is required at every output stage."),
("Explain how recommendation systems can serve a film production platform.", "Recommendation systems for film production: (1) Reference material recommendation -- when a director inputs a scene's tone description, the system recommends relevant reference films, sequences, and images from a curated database; trained on director taste profiles developed through past interactions. (2) Script analysis comparables -- given the script's tone, genre, structure, and character types, recommend comparable produced films ('your project's structural profile is closest to these produced films by these directors'); useful for producer positioning and director research. (3) Location recommendations -- given script requirements (period, geography, interior/exterior, scale), recommend specific locations from the production's location library and from partner databases, ranked by match score and availability. (4) Crew recommendations -- given a production's visual style, genre, and budget range, recommend DPs, editors, composers, and production designers whose prior work matches; based on filmography analysis and style classification. (5) Scheduling optimisation -- given the breakdown of scenes, actors, and locations, recommend optimal shooting schedule sequences that minimise costs and company moves; AI-assisted scheduling (Movie Magic has begun integrating ML-based schedule optimisation). (6) Sound design suggestions -- given a scene's visual composition and emotional key, recommend sound design approaches and specific sound effects from a categorised library. (7) Music cue suggestions -- suggest temp track cues from the music library that match scene duration, emotional arc, and tempo; useful for early rough cut assembly before the composer is working."),
("How does AI summarisation apply to a film production context?", "AI summarisation for film production use cases: (1) Script summarisation -- generating a 2-5 page treatment from a full screenplay; a one-page logline; a scene-by-scene beat sheet; useful for producer presentations without the recipient reading the full script. (2) Meeting and note summarisation -- production meetings, creative sessions, and dailies reviews generate extensive notes; AI summarisation extracts action items, decisions, and unresolved questions; saves a coordinator hours of note-taking and organisation. (3) Dailies summary -- after each shooting day, generate a summary of what was shot, which scenes are complete, which need additional coverage, and which performances the director flagged; compiled from the script supervisor's notes and the director's annotations. (4) Performance note tracking -- an AI assistant listens to or reads the director's on-set performance notes and produces a structured summary per actor per scene, categorised by take number and type of adjustment requested. (5) Revision comparison summary -- when a new script revision arrives, generate a summary of all changes from the previous version categorised by scene, character impact, and production implication. (6) Research summarisation -- given a topic relevant to the production (a historical period, a technical process, a specific location's history), summarise relevant research into a concise briefing for the director. (7) Day-out-of-days summarisation -- for complex productions, summarise the shooting schedule in human-readable form for each department, highlighting their specific days, equipment requirements, and location assignments. Quality requirement: summarisation AI must preserve accuracy; a single factual error in a production summary can cause a costly mistake; all AI summaries should be reviewed before distribution."),
("Explain embeddings and semantic search in a film production asset management context.", "Semantic search using embeddings in film production: (1) The problem with keyword search -- a production archivist searching for 'the scene where Sarah confronts her father in the kitchen' will fail with keyword search if the scene header reads 'INT. BROWNSTONE - MORNING' and has no metadata; semantic search understands intent. (2) How embeddings work -- a text embedding model converts a description into a high-dimensional vector that encodes its semantic meaning; similar meanings produce similar vectors regardless of exact wording. Images and audio can also be embedded. (3) Corpus building -- every script scene, shot note, call sheet entry, location description, dailies frame annotation, and asset description is embedded and stored in a vector database (Pinecone, Weaviate, Qdrant, pgvector). (4) Search applications: (a) Script search: 'Find all scenes where characters are physically separated by an obstacle' -- the search returns all scenes that semantically match this description even without those exact words. (b) Reference image search: upload a painting as the query; retrieve compositionally similar shots from the production's own footage or from a reference library. (c) Location search: 'Find a location that feels industrial and isolated with natural light' -- retrieves location photographs ranked by semantic match. (d) Footage search: 'Find takes where the actor looks genuinely surprised rather than performing surprise' -- this requires computer vision embeddings combined with a natural language query. (5) Production benefit: semantic search replaces the hours a production coordinator spends manually cross-referencing documents; surfaces relevant material from large archives in seconds."),
("Explain prompt engineering principles for film production AI tools.", "Prompt engineering for film production: the quality of AI output is proportional to the quality of the prompt. Principles for film production contexts: (1) Role specification -- tell the AI what role to play: 'You are an experienced first AD; given the following script pages, identify the five most complex scheduling challenges and propose solutions.' Role framing activates relevant domain knowledge in the model. (2) Context provision -- provide full context rather than assuming the AI knows your project: scene description, tone, genre, character relationships, visual references, and any constraints. A prompt with rich context produces specific, actionable output; a vague prompt produces generic output. (3) Output format specification -- specify the exact format you need: 'Generate a shot list in a table with columns for: Shot Number, Shot Type, Lens, Camera Movement, Description. Include 12 shots for this scene.' Structured output specification produces reliably formatted output. (4) Constraint definition -- explicitly state constraints: 'This is a one-location, two-character dialogue scene with no VFX and a one-day shoot window; suggest coverage that can be achieved in 8 hours with a crew of 20.' (5) Iteration framing -- for complex creative tasks, use iterative prompts: generate a first version, review it, then refine with specific feedback: 'The scene breakdown is good; now revise it to account for the fact that Character B has a physical disability that affects their blocking.' (6) Example provision (few-shot prompting) -- show the AI one or two examples of the output format and quality you want before asking it to generate a new instance. (7) Temperature for creative vs analytical tasks -- for factual analysis (script breakdown, scheduling), use lower temperature (more deterministic); for creative ideation (shot list brainstorming, dialogue suggestions), higher temperature produces more varied outputs."),
("What is agent design and how does it apply to a film production AI assistant?", "Agent design for a film production AI assistant: An agent is an AI system that can take actions in the world autonomously -- not just answering questions but planning and executing multi-step tasks. Film production assistant agent architecture: (1) Tool use -- the agent can call external tools: the script database (retrieve the current draft of any scene), the scheduling system (query the current schedule, propose modifications), the asset library (search for props, locations, references), the crew directory (look up contact information and availability). (2) Memory -- the agent maintains a persistent memory of the project's state: characters, scenes, locations, decisions made, outstanding issues; can be queried ('What location was approved for scene 47?') and updated ('We've changed scene 47's location to the warehouse'). (3) Planning -- given a complex task ('Create a preliminary shot list for scenes 12-18, taking into account the approved locations and the director's visual concept'), the agent decomposes the task into steps, executes each step using available tools, and synthesises a complete output. (4) Human-in-the-loop design -- all consequential decisions (schedule changes, budget modifications, location commitments) require human approval before the agent executes them; the agent presents options and recommendations but does not act without approval. (5) Error handling -- when the agent encounters missing information or ambiguity, it asks a clarifying question rather than guessing; production errors caused by wrong assumptions are costly. (6) Integration triggers -- the agent responds to events in connected systems (a script revision uploaded triggers a notification 'Scene 23 has changed; here is how it affects tomorrow's schedule and shot list')."),
("How does human-in-the-loop AI design apply to creative film production tools?", "Human-in-the-loop (HITL) design for film production AI: Creative professionals, particularly directors, require that AI tools support their judgment rather than replace it. HITL principles for film AI: (1) AI as a first draft, not the final word -- the AI generates candidate shot lists, scene breakdowns, schedule options, or script notes; the human reviews, selects, and modifies; the AI learns from the selection to improve future suggestions. (2) Confidence communication -- the AI should communicate its confidence level with each output; a high-confidence schedule suggestion based on complete data is treated differently from a low-confidence creative suggestion; uncertainty about location availability or actor availability should always be flagged explicitly. (3) Explainability -- when the AI makes a recommendation, it should explain its reasoning: 'I suggest shooting scenes 12 and 18 on the same day because they share the warehouse location; this saves a company move and reduces the logistics cost by approximately $8,000.' The director can evaluate this reasoning and accept or reject it. (4) Override mechanisms -- the director must be able to override any AI suggestion easily; the override should be recorded (for model improvement) but never resisted. (5) Approval gates -- decisions with production consequences (scheduling commitments sent to cast and crew, location bookings, equipment orders) are never executed automatically; they require an explicit human approval action. (6) Taste calibration -- the AI's creative suggestions should be calibrated to the director's specific taste, not generic 'best practice'; this requires the system to learn from the director's historical decisions and explicit feedback over time."),

# ── PRODUCT AND UX FOR FILM TEAMS ─────────────────────────────────────────────
("What makes a great UX for a director's AI assistant on set?", "UX design for a director's on-set AI assistant: The on-set environment is high-pressure, time-constrained, and physically demanding. UX requirements: (1) Speed -- any task that takes more than 15 seconds is too slow for on-set use; the director is under constant time pressure; the tool must return results before the director has moved on to the next problem. (2) Low friction input -- voice input is the highest priority (the director's hands are often occupied or dirty); typed input must be minimal; no long form queries required; simple natural language ('What's the next shot?', 'How long until we lose the light?'). (3) High information density output -- the director needs a lot of information in a small space; dashboards should be dense but readable; the most critical information (what we're shooting now, what's next, how much time we have) must be visible without scrolling. (4) Contextual intelligence -- the tool should know what scene is being shot, which actors are on set, what the time is, and what the schedule says; it should surface relevant information proactively rather than requiring the director to ask. (5) Offline capability -- set connectivity is often unreliable; core functions (shot list, schedule, notes) must work without internet access. (6) Handoff to other tools -- the director's assistant and 1st AD use the same platform; information must flow between users without re-entry; a shot completed by the director should automatically update the 1st AD's progress view. (7) Minimal cognitive load -- on set, cognitive resources are fully committed to the creative and logistical work; the tool should never require the director to think about how to use it."),
("Explain mobile-first production usability for film crews.", "Mobile-first design for film production tools: The majority of on-set use is on smartphones and tablets; desktops are for office pre-production work. Mobile-first requirements: (1) Thumb-zone design -- primary actions (mark a take good, advance to the next shot, send a note) must be reachable with one thumb in landscape or portrait mode; no critical functions in the corners or top of the screen. (2) Large tap targets -- on-set use occurs with gloves, cold weather, sweaty hands, or while walking; tap targets must be at least 44x44 pixels with generous spacing between adjacent targets. (3) Bright ambient conditions -- sets are often extremely bright (outdoor sun, powerful film lights); displays must be legible at maximum brightness; high contrast design. (4) Noise environment -- audio alerts and voice output must compete with set noise (generators, crew noise, vehicle movement); either configurable audio with vibration backup or visual-only notification design. (5) Battery consciousness -- a 12-hour shooting day requires a tool that does not drain the battery; background processes must be minimal; offline caching reduces network requests. (6) Quick navigation -- the most common navigations (current scene to next scene, shot list to schedule) must require maximum two taps; deep hierarchical navigation is appropriate for desktop, not mobile. (7) Camera integration -- production apps that allow the director or script supervisor to photograph continuity elements (props, set dressing, makeup) directly within the app, tagged to the relevant scene, save enormous amounts of time. (8) Role-specific views -- the director's mobile view shows shot list and scene intent; the 1st AD's view shows schedule and time; the script supervisor's view shows takes and continuity; the DP's view shows lens and lighting notes."),
("How do you design for context-aware suggestions in a film production AI tool?", "Context-aware suggestion design for film production: Context-aware suggestions surface the right information at the right time without the user needing to ask. Implementation principles: (1) State tracking -- the system knows the current production state: which scene is being shot, which take is in progress, how much time has elapsed, how much time remains in the shooting day, which shots are complete, which are still outstanding. From this state, it can surface relevant suggestions proactively. (2) Time-triggered suggestions -- 30 minutes before a meal break: 'You have 30 minutes; the next shot on the list will take approximately 20 minutes; this is achievable before the break.' 10 minutes before the estimated location wrap: 'Wrap is approaching; shots 5 and 7 are not yet captured; do you want to shoot them in order or prioritise shot 7 as the more critical coverage?' (3) Take-triggered suggestions -- after each take marked good: 'Shot 3 is complete. Shot 4 requires repositioning the camera to the opposite side (approximately 12 minutes). Given the remaining schedule, do you want to proceed with 4 or jump to 5 which can be captured from the current position?' (4) Problem-triggered suggestions -- if the day is running behind schedule: 'You are 45 minutes behind; to make up time, shots 8, 11, and 14 could be simplified to a single setup each; this would save approximately 30 minutes without significantly reducing coverage.' (5) Pre-shoot suggestions -- each morning before the shooting day begins: a summary of the day's scenes, the top three technical challenges, and the director's notes for each scene."),
("Explain how trust and reliability design applies to AI tools used by directors.", "Trust and reliability design for director-facing AI tools: Directors make high-stakes decisions based on information from their tools; an error has significant financial and creative consequences. Design principles: (1) Accuracy before completeness -- it is better to provide a smaller set of highly accurate information than a comprehensive set with some errors; errors, once experienced, destroy trust in the entire system. (2) Source citation -- every fact or suggestion should indicate its source: 'According to the current schedule (rev. 3, issued Oct 15), scene 23 is allocated 4 hours.' This allows the director to evaluate reliability independently. (3) Uncertainty communication -- when the system is not certain, it must say so explicitly: 'Location availability for scene 45 has not been confirmed; this is based on the scouting report dated Oct 10.' Never present uncertain information with false confidence. (4) Error acknowledgment -- when the system makes an error and the user corrects it, acknowledge the correction and explain how it will prevent the same error: 'Thank you; I've updated the location status. I'll cross-check location confirmations against the production coordinator's approval before surfacing them as confirmed in the future.' (5) Consistent behaviour -- a tool that behaves differently in similar situations is not trusted; core functions must produce consistent results across sessions. (6) Graceful degradation -- when the system cannot complete a task (connectivity lost, data unavailable), it should fail gracefully with a clear explanation and manual fallback instruction, not silently or with a confusing error. (7) Track record display -- show the system's track record: 'Schedule time estimates have been accurate to within 15% for 87% of shots on this production.' Demonstrates earned reliability."),

# ── DATA AND SYSTEMS ──────────────────────────────────────────────────────────
("Explain data pipeline design for a film production management platform.", "Film production data pipeline design: A production management platform ingests, transforms, and serves data from multiple sources to multiple consumers. Pipeline architecture: (1) Ingestion layer -- sources: script uploads (PDF, Final Draft, Highland formats); call sheet submissions (PDF or structured form); dailies metadata from the lab or digital workflow; VFX tracking spreadsheets; budget and actuals from production accounting software; location photos; crew contacts. Each source requires a specific ingestion connector and parser. (2) Parsing and normalisation -- script parser extracts: scenes (number, header, INT/EXT, DAY/NIGHT), characters, dialogue, action elements; normalises to a standard schema regardless of source format. Call sheet parser extracts: shoot date, scenes scheduled, cast calls, crew calls, locations. (3) Storage -- structured data (scene breakdowns, schedules, cast, crew, budget) in a relational database (PostgreSQL); unstructured assets (scripts, PDFs, images, video clips) in object storage (S3); full-text and semantic search via Elasticsearch or pgvector. (4) Processing -- automated breakdown generation from parsed scripts; schedule conflict detection (same actor scheduled for two concurrent scenes); budget actuals reconciliation (compare actuals from accounting to budgeted line items). (5) Serving layer -- REST API for web and mobile clients; WebSocket for real-time collaborative editing (multiple users editing the schedule simultaneously); GraphQL for flexible data access patterns in the production dashboard. (6) Data model key entities: Production -> Scenes -> Shots -> Takes; Cast -> Call Times; Crew -> Departments; Locations -> Availability; Assets -> Tags."),
("Explain how APIs enable film production platform integrations.", "API design and integration for film production platforms: A production management platform must integrate with the ecosystem of tools already used in film production. Integration architecture: (1) Core integrations -- Movie Magic Scheduling/Budgeting (industry-standard scheduling tool; import/export via XML); Final Draft (script format; FDX file API); EP Budgeting (industry-standard budgeting); Shotgun/ShotGrid (VFX and animation project management; REST API); Frame.io (video review; OAuth-based REST API for footage upload, comment retrieval, approval status). (2) Communication integrations -- email (SendGrid API for call sheet distribution); SMS (Twilio for urgent day-of notifications); Slack or Teams (production channel notifications: 'Scene 23 is now complete; next shot in 10 minutes'). (3) API design principles for film production: (a) Idempotency -- production databases are updated by multiple users simultaneously; ensure that duplicate writes are handled gracefully (uploading the same dailies file twice should not create duplicate records). (b) Versioning -- the production industry adopts tools slowly; API versioning ensures that a DP's iPad app built on v1 still works when v2 is released. (c) Rate limiting -- large productions may have hundreds of crew members simultaneously syncing data; implement rate limits per user and per production to prevent server overload. (d) Webhook support -- enable connected tools to receive event notifications (scene status changes, call sheet updates, schedule changes) rather than polling. (e) Offline sync protocol -- mobile clients on sets must work offline and sync bidirectionally when connectivity returns."),
("Explain event-driven system design for a real-time production update platform.", "Event-driven architecture for real-time film production updates: Traditional request-response APIs are insufficient for a production environment where dozens of crew members need to see schedule changes, shot completions, and notes in real time. Event-driven design: (1) Event types -- SceneStatusChanged (a scene changes from Not Started to In Progress to Complete); ShotCompleted (a specific shot marked complete by the 1st AD); CallTimeChanged (an actor's call time modified on the call sheet); LocationChanged (a scene's location has been updated); NoteAdded (director adds a note to a scene). (2) Event bus -- all events published to a central message broker (Kafka for high-throughput production environments; AWS EventBridge or Pusher Channels for simpler deployments); events are durably stored and replayed to new subscribers. (3) Subscribers -- mobile clients of all crew members; push notification service (sends phone alerts for high-priority events); analytics system (tracks production velocity metrics); scheduling system (updates schedule status automatically when scenes complete). (4) Real-time delivery -- WebSocket connections from mobile and web clients subscribe to events relevant to their role; when the 1st AD marks shot 3 complete on their tablet, every subscribed client (DP, director, producer) sees the update within 2 seconds. (5) Ordering and consistency -- events within a single entity (a specific scene) must be processed in order; use partition keys on the event bus to ensure ordered processing per entity. (6) Offline handling -- mobile clients queue events generated offline; when connectivity returns, events are published in order with timestamps; conflict resolution rules handle cases where two users made conflicting changes offline."),
("Explain database design for a film script and production asset management system.", "Database schema design for film production management: (1) Core entity relationships: Production (1) -> Many Drafts; Draft (1) -> Many Scenes; Scene (1) -> Many Shots; Shot (1) -> Many Takes; Scene (M) -> Many Characters (M) [through SceneCast]; Character (M) -> One Actor (for cast productions). (2) Script versioning -- scripts are versioned documents; each draft is a versioned snapshot; scenes are versioned within drafts; a scene deleted in one draft is marked as OMITTED, not deleted from the database (preserves the numbering convention). (3) Scheduling entities: ScheduleDay (1) -> Many ScheduledScene; ScheduledScene links a Scene to a ScheduleDay with allocated time and sequence order; Actor links to ScheduledScene through Call (a specific actor's call time for a specific scheduled scene). (4) Asset entities: Asset (id, production_id, type [prop/costume/vehicle/location], name, description, status); AssetSceneLink (asset_id, scene_id, notes). (5) Metadata and tagging: all major entities support tags (flexible key-value pairs for production-specific metadata); full-text search indexed on scene descriptions, dialogue, and character names. (6) Access control schema: User (id, email, role[director/producer/crew]); ProductionMember (production_id, user_id, role, permissions); row-level security ensures crew members only access their own production's data. (7) Audit trail: every write operation logged to an audit table (entity_type, entity_id, action, old_value, new_value, user_id, timestamp); enables forensic review of any change to production documents."),
("Explain low-latency system design considerations for a mobile-first production app.", "Low-latency design for a mobile production app: A director asking 'What's the next shot?' needs an answer in under 500ms; latency above 1 second breaks the on-set workflow. Strategies: (1) Aggressive caching -- the entire production's current-day data (schedule, shot list, scene notes, cast calls) is preloaded onto the device during the morning sync before the shoot day begins; all read operations during the day serve from local cache with no network round-trip. (2) Optimistic UI updates -- when the 1st AD marks a shot complete, the local UI updates immediately; the server confirmation happens asynchronously in the background; if the server rejects (rare), the UI rolls back with an error notification. (3) Delta syncing -- instead of syncing the entire production database at each sync, only sync changes since the last sync timestamp; reduces sync time from minutes (for large productions) to seconds. (4) Read replicas -- serve read requests from geographically distributed database read replicas; a production shooting in the UK doesn't need to query a US-east server for every read. (5) CDN for static assets -- call sheet PDFs, location photos, and reference images served via CDN (CloudFront, Fastly) from an edge node close to the production location. (6) Connection quality adaptation -- detect network quality and adapt; on poor connectivity, serve only critical data (shot list, schedule); on good connectivity, serve full-quality assets (high-res location photos, reference video). (7) Background sync prioritisation -- the OS may throttle background sync; use foreground sync for critical updates (call time changes) and background sync for non-urgent data (analytics, archives)."),
]

assert len(pairs) >= 15, f"Only {len(pairs)} pairs"
existing = sum(1 for _ in OUT.open()) if OUT.exists() else 0
print(f"Existing pairs: {existing}")

with OUT.open("a") as f:
    for q, a in pairs:
        f.write(json.dumps({"messages": [
            {"role": "user", "content": q},
            {"role": "assistant", "content": a}
        ]}) + "\n")

total = sum(1 for _ in OUT.open())
print(f"Total after film_part3: {total}")
print("Film Part 3 DONE")
